import os
import torch


class Config:
    # --------------------------------------------------------------------------
    # Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for caching and model artifacts
    # Using 'idea_23' as requested in the requirements
    WORKING_DIR = "./working/idea_23"
    os.makedirs(WORKING_DIR, exist_ok=True)

    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = "./submission/submission.csv"

    # --------------------------------------------------------------------------
    # Data / Preprocessing
    # --------------------------------------------------------------------------
    IMG_SIZE = 224
    NUM_SLICES = 3
    STRIDE = 5

    # ROI Selection Hyperparameters
    # We downsample to this size to select the "brightest" slice based on
    # region intensity rather than single-pixel noise.
    ROI_DOWNSAMPLE_SIZE = 32
    ROI_DEPTH_MIN = 0.15
    ROI_DEPTH_MAX = 0.85

    # Input channels: 4 modalities * 3 slices = 12 channels
    IN_CHANNELS = 12

    # --------------------------------------------------------------------------
    # Model Architecture
    # --------------------------------------------------------------------------
    BACKBONE = "efficientnet_b0"
    NUM_CLASSES = 1  # Binary classification

    # --------------------------------------------------------------------------
    # Training Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42
    BATCH_SIZE = 32
    EPOCHS = 10

    # Optimization
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2

    # Early Stopping
    PATIENCE = 3

    # --------------------------------------------------------------------------
    # System
    # --------------------------------------------------------------------------
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4
